const TOPIC_LABEL: Record<Topic, string> = {
  love: "Tình cảm – hôn nhân", work: "Công việc – sự nghiệp", money: "Tài chính – kinh doanh",
  family: "Gia đạo", study: "Học tập – thi cử", travel: "Xuất hành – đi lại", general: "Vấn đề tổng quát"
};

function classify(question: string): Topic {
  const q = question.toLowerCase();
  if (/yêu|tình cảm|tình duyên|hôn nhân|cưới|người yêu|chia tay|vợ|chồng|crush|quan hệ/.test(q)) return "love";
  if (/việc|công việc|sự nghiệp|nghề|xin việc|nghỉ việc|đổi việc|kinh doanh|dự án|khởi nghiệp|đối tác/.test(q)) return "work";
  if (/tiền|tài chính|đầu tư|vốn|lãi|lỗ|nợ|mua|bán|giàu|thu nhập|kinh doanh/.test(q)) return "money";
  if (/gia đình|gia đạo|cha|mẹ|con cái|anh chị|người thân/.test(q)) return "family";
  if (/học|thi cử|thi|trường|bằng cấp|kiến thức/.test(q)) return "study";
  if (/đi đâu|xuất hành|du lịch|di chuyển|chuyến đi|chuyển nhà/.test(q)) return "travel";
  return "general";
}

